@prefix dqv: <http://www.w3.org/ns/dqv#> .
@prefix oa: <http://www.w3.org/ns/oa#> .
@prefix schema1: <http://schema.org/> .
@prefix sh: <http://www.w3.org/ns/shacl#> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .

[] a sh:ValidationReport ;
    sh:conforms false ;
    sh:result [ a sh:ValidationResult ;
            sh:focusNode [ a dqv:QualityAnnotation ;
                    schema1:name "ISO 19115 compliance statement" ;
                    oa:hasBody "Metadata for this dataset were prepared and validated against ISO 19115-1:2014. All mandatory elements are populated and the record passed the national profile conformance check on 2024-03-11." ;
                    oa:hasTarget 42 ;
                    oa:motivatedBy dqv:qualityAssessment ] ;
            sh:resultMessage "oa:hasTarget, if given, references the annotated resource by IRI" ;
            sh:resultPath oa:hasTarget ;
            sh:resultSeverity sh:Info ;
            sh:sourceConstraintComponent sh:NodeKindConstraintComponent ;
            sh:sourceShape [ sh:message "oa:hasTarget, if given, references the annotated resource by IRI" ;
                    sh:nodeKind sh:IRI ;
                    sh:path oa:hasTarget ;
                    sh:severity sh:Info ] ;
            sh:value 42 ] .

@prefix sh: <http://www.w3.org/ns/shacl#> .
